/// (Highstock) Keyboard navigation for a series
class HCSeriesAccessibilityKeyboardNavigationOptionsObject implements HCOption {
  const HCSeriesAccessibilityKeyboardNavigationOptionsObject({
    this.enabled,
  });

  /// (Highstock) Enable/disable keyboard navigation support for a specific series.
  final bool? enabled;

  @override
  Map<String, dynamic> toJson() {
    final Map<String, dynamic> json = <String, dynamic>{};
    if (enabled != null) {
      json['enabled'] = enabled;
    }
    return json;
  }
}

/// (Highstock) Accessibility options for a series.
class HCSeriesAccessibilityOptionsObject implements HCOption {
  const HCSeriesAccessibilityOptionsObject({
    this.description,
    this.descriptionFormat,
    this.enabled,
    this.exposeAsGroupOnly,
    this.keyboardNavigation,
    this.point,
  });

  /// (Highstock) Provide a description of the series, announced to screen readers.
  final String? description;

  /// (Highstock) Format to use for describing the data series group to assistive technology - including screen readers.
  final String? descriptionFormat;

  /// (Highstock) Enable/disable accessibility functionality for a specific series.
  final bool? enabled;

  /// (Highstock) Expose only the series element to screen readers, not its points.
  final bool? exposeAsGroupOnly;

  /// (Highstock) Keyboard navigation for a series
  final HCSeriesAccessibilityKeyboardNavigationOptionsObject?
      keyboardNavigation;

  /// (Highstock) Point accessibility options for a series.
  final dynamic point;

  @override
  Map<String, dynamic> toJson() {
    final Map<String, dynamic> json = <String, dynamic>{};
    if (description != null) {
      json['description'] = description;
    }
    if (descriptionFormat != null) {
      json['descriptionFormat'] = descriptionFormat;
    }
    if (enabled != null) {
      json['enabled'] = enabled;
    }
    if (exposeAsGroupOnly != null) {
      json['exposeAsGroupOnly'] = exposeAsGroupOnly;
    }
    if (keyboardNavigation != null) {
      json['keyboardNavigation'] = keyboardNavigation!.toJson();
    }
    if (point != null) {
      json['point'] = hcJsonValue(point);
    }
    return json;
  }
}

